const mime=String(b.mime||'application/pdf').toLowerCase();
if(data.length<200) return [{json:{skip:true}}];
const isPdf=/pdf/.test(mime);
const part=isPdf?{type:'file',file:{filename:'purchase-order.pdf',file_data:'data:application/pdf;base64,'+data}}:{type:'image_url',image_url:{url:'data:'+(/png/.test(mime)?'image/png':'image/jpeg')+';base64,'+data}};
const prompt=['This is a purchase order created in QuickBooks by Chelmsford Building Services Ltd (UK building contractor) and sent to a supplier.',
'Read it and reply with ONLY a JSON object, no other text, with these keys:',
'po_no: the PO number exactly as printed',
'supplier: the supplier/vendor company name (not Chelmsford Building Services)',
'po_date: the PO date as YYYY-MM-DD (source dates are UK format DD/MM/YYYY)',
'expected_delivery: the expected/required delivery or due date as YYYY-MM-DD, or "" if none',
'ship_to: the delivery/ship-to address as one line, or ""',
'job_ref: a ServiceM8 job number if one appears (a number of 3 to 6 digits in a job, customer, project, memo or reference field, or in the ship-to), otherwise ""',
'deliver_guess: "Yard" if the ship-to is Chelmsford Building Services own premises or yard, "Site" if it is a different site address, otherwise ""',
'type_guess: "Plant" if this is for plant or equipment hire (hire periods, per week/day rates, off-hire, machines, scaffold, skips, welfare units, generators), "Material" if it is goods/materials, otherwise ""',
'hire_end: an off-hire or hire end date as YYYY-MM-DD if stated, otherwise ""',
'subtotal: total before VAT as a number, or ""',
'vat: VAT amount as a number, or ""',
'total: total including VAT as a number, or ""',
'lines: array of items, each {"desc": text, "qty": number or "", "unit": text or "", "cost": unit rate before VAT as a number or ""}',
'Do not guess values that are not on the document; use "" instead.'].join('\n');
return [{json:{skip:false,req:{model:'anthropic/claude-haiku-4.5',max_tokens:2000,temperature:0,messages:[{role:'user',content:[part,{type:'text',text:prompt}]}]}}}];

const r=$input.first().json||{};
if($('Read Prep').first().json.skip===true) return [{json:{ok:false,message:'No file received'}}];
let txt='';try{const c=r.choices&&r.choices[0]&&r.choices[0].message&&r.choices[0].message.content;txt=Array.isArray(c)?c.map(x=>x&&x.text||'').join('\n'):String(c||'');}catch(e){}
if(!txt&&Array.isArray(r.content))txt=r.content.filter(c=>c&&c.type==='text').map(c=>c.text).join('\n');
const m=txt.match(/\{[\s\S]*\}/);if(!m) return [{json:{ok:false,message:'Could not read the PO',detail:String((r.error&&r.error.message)||'').slice(0,200)}}];
let o={};try{o=JSON.parse(m[0]);}catch(e){return [{json:{ok:false,message:'Could not read the PO'}}];}
const S=v=>v==null?'':String(v).trim();
const D=v=>{v=S(v);if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;const x=v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/);if(x){const y=x[3].length===2?'20'+x[3]:x[3];return y+'-'+('0'+x[2]).slice(-2)+'-'+('0'+x[1]).slice(-2);}return '';};
const N=v=>{if(v===''||v==null)return '';const n=parseFloat(String(v).replace(/[^0-9.\-]/g,''));return isNaN(n)?'':Math.round(n*100)/100;};
const pick=(v,a)=>a.indexOf(S(v))>-1?S(v):'';
const lines=(Array.isArray(o.lines)?o.lines:[]).slice(0,60).map(l=>({desc:S(l&&l.desc).slice(0,200),qty:N(l&&l.qty),unit:S(l&&l.unit).slice(0,20),cost:N(l&&l.cost)})).filter(l=>l.desc);
const job=S(o.job_ref).replace(/[^0-9]/g,'');
return [{json:{ok:true,po:{po_no:S(o.po_no).slice(0,40),supplier:S(o.supplier).slice(0,120),po_date:D(o.po_date),expected_delivery:D(o.expected_delivery),ship_to:S(o.ship_to).slice(0,300),job_ref:/^\d{3,6}$/.test(job)?job:'',deliver_guess:pick(o.deliver_guess,['Site','Yard']),type_guess:pick(o.type_guess,['Material','Plant']),hire_end:D(o.hire_end),subtotal:N(o.subtotal),vat:N(o.vat),total:N(o.total),lines:lines}}}];

